#include "Monstey_FearDbResources.hpp"
#include "Monstey_Json.hpp"
#include <array>
#include <bit>
#include <fstream>
#include <iostream>
using namespace Monstey;
namespace {
using Monstey_U32=std::uint32_t;std::uint64_t Monstey_Groups=0,Monstey_Cases=0,Monstey_Checks=0;
static_assert(std::endian::native==std::endian::little);
void Monstey_Check(bool value,const char*text){++Monstey_Checks;if(!value)throw std::runtime_error(text);}
void Monstey_Add(std::vector<std::uint8_t>&wire,Monstey_U32 word){for(unsigned i=0;i<4;++i)wire.push_back(static_cast<std::uint8_t>(word>>(8*i)));}
std::vector<std::uint8_t> Monstey_Wire(Monstey_U32 pool,std::size_t prefix=0){std::vector<std::uint8_t> wire(prefix,0xcd);for(auto n:std::array<Monstey_U32,7>{0x42444147,3,pool,1,0,0,0})Monstey_Add(wire,n);wire.resize(prefix+28+pool,0x61);Monstey_Add(wire,0);return wire;}
Monstey_U32 Monstey_Get(const Monstey_FearDbPackedImage&image,Monstey_U32 at){Monstey_U32 word=0;for(unsigned i=0;i<4;++i)word|=Monstey_U32(image.allocation.at(at-image.base+i))<<(8*i);return word;}
std::size_t Monstey_Extent(std::uint64_t word){for(std::size_t n=0;n<8;++n)if(((word>>(n*8))&255u)==0)return n+1;throw std::runtime_error("Fixture extent");}
void Monstey_Run(Monstey_U32 pool,std::size_t prefix,std::uint64_t initial_calls,bool counter_alias,bool unrelated_first){
 auto wire=Monstey_Wire(pool,prefix);const auto original=wire;Monstey_FearDbPackedInput input{wire,prefix,initial_calls};const auto field=counter_alias?reinterpret_cast<const std::uint8_t*>(&input.read_calls):reinterpret_cast<const std::uint8_t*>(&input.position);const auto first=Monstey_Extent(counter_alias?initial_calls+1:prefix+28);const auto final_value=counter_alias?initial_calls+3:prefix+32u+pool;const auto graph=Monstey_Extent(final_value);auto loaded=Monstey_FearDbLoadPacked(input,std::span<const std::uint8_t>(field,8),0x30000000);Monstey_Check(loaded.image.has_value(),"real alias loader produced resource");const auto db=loaded.image->database;const auto used=pool+20u+static_cast<Monstey_U32>(graph);Monstey_Check(loaded.image->used_bytes==used&&loaded.allocation_bytes==pool+36u+first&&Monstey_Get(*loaded.image,db+12)==0x30000000u+used,"resource receives corrected post-count name layout");Monstey_Check(Monstey_Get(*loaded.image,db+16)==0,"loader reference starts0");
 auto other_wire=Monstey_Wire(0);Monstey_FearDbPackedInput other_input{other_wire};auto other=Monstey_FearDbLoadPacked(other_input,std::array<std::uint8_t,2>{'u',0},0x31000000);Monstey_Check(other.image.has_value(),"unrelated real resource loaded");const auto other_db=other.image->database;Monstey_FearDbResources resources;
 if(unrelated_first){resources.allocations.push_back(std::move(*other.image));resources.allocations.push_back(std::move(*loaded.image));}else{resources.allocations.push_back(std::move(*loaded.image));resources.allocations.push_back(std::move(*other.image));}
 Monstey_FearDbRegisterLoaded(resources,other_db);const auto other_index=unrelated_first?0u:1u;const auto other_bytes=resources.allocations[other_index].allocation;Monstey_FearDbRegisterLoaded(resources,db);Monstey_FearDbRetainSelected(resources,db);const auto index=unrelated_first?1u:0u;Monstey_Check(resources.cache==std::vector<Monstey_U32>{other_db,db}&&Monstey_Get(resources.allocations[index],db+16)==2,"real registration and retain compose after alias load");
 const auto one=Monstey_FearDbReleaseDatabase(resources,db);Monstey_Check(one.kind==Monstey_FearDbReleaseKind::retained&&one.counter_after==1&&resources.allocations.size()==2,"first release retains alias resource");const auto zero=Monstey_FearDbReleaseDatabase(resources,db);Monstey_Check(zero.kind==Monstey_FearDbReleaseKind::freed&&zero.allocation_base==0x30000000&&zero.removed_cache_index==1,"last release uses correct allocation and cache identity");Monstey_Check(resources.cache==std::vector<Monstey_U32>{other_db}&&resources.allocations.size()==1&&resources.allocations[0].allocation==other_bytes,"unrelated resource and cache order survive");const auto last=Monstey_FearDbReleaseDatabase(resources,other_db);Monstey_Check(last.kind==Monstey_FearDbReleaseKind::freed&&resources.allocations.empty()&&resources.cache.empty(),"all real allocations release exactly once");Monstey_Check(input.position==prefix+32u+pool&&input.read_calls==initial_calls+3&&wire==original,"caller input retains cursor progress and original bytes");++Monstey_Cases;
}
void Monstey_Positions(){for(auto pair:std::array<std::array<std::size_t,2>,5>{{{0,228},{1,227},{0,224},{223,1},{65503,257}}})for(bool order:std::array<bool,2>{false,true})Monstey_Run(static_cast<Monstey_U32>(pair[1]),pair[0],0,false,order);++Monstey_Groups;}
void Monstey_ReadCalls(){for(auto initial:std::array<std::uint64_t,3>{0,254,65534})for(auto pool:std::array<Monstey_U32,2>{0,228})for(bool order:std::array<bool,2>{false,true})Monstey_Run(pool,0,initial,true,order);++Monstey_Groups;}
}
int main(int argc,char**argv){try{if(argc!=2)throw std::runtime_error("NEW report required");Monstey_Positions();Monstey_ReadCalls();std::ofstream(argv[1],std::ios::binary)<<Monstey_Json::object({{"schema","Monstey.FearResourceAliasComposition/1"},{"passed",true},{"groups",Monstey_Groups},{"cases",Monstey_Cases},{"checks",Monstey_Checks},{"real_loader_and_resource_helpers",true},{"original_program_executed",false}}).dump(2)<<'\n';std::cout<<"PASS "<<Monstey_Groups<<" groups "<<Monstey_Cases<<" cases "<<Monstey_Checks<<" checks\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
